SELECT *
FROM attendance_record
WHERE tenant_id = #{tenantId}

    AND store_id IN
    #{sid}

AND check_date BETWEEN #{startDate} AND #{endDate}
AND deleted = 0
ORDER BY check_date, employee_id

SELECT ar.*, pe.employee_name, pe.position, ps.store_name FROM attendance_record ar LEFT JOIN pos_employee pe ON ar.employee_id = pe.id LEFT JOIN pos_store ps ON ar.store_id = ps.id WHERE ar.deleted = 0 AND ar.tenant_id = #{tenantId}
AND ar.store_id IN #{sid}
AND (#{employeeId} IS NULL OR ar.employee_id = #{employeeId}) AND (#{startDate} IS NULL OR ar.check_date >= #{startDate}) AND (#{endDate} IS NULL OR ar.check_date <= #{endDate}) ORDER BY ar.check_date DESC, ar.employee_id
